#include <bits/stdc++.h>
using namespace std;

struct P {
    long double x, y;
};

static inline long double cross(const P& a, const P& b) {
    return a.x * b.y - a.y * b.x;
}
static inline P operator+(const P& a, const P& b) { return {a.x + b.x, a.y + b.y}; }
static inline P operator-(const P& a, const P& b) { return {a.x - b.x, a.y - b.y}; }
static inline P operator*(const P& a, long double s) { return {a.x * s, a.y * s}; }

static long double polygon_area(const vector<P>& poly) {
    int n = (int)poly.size();
    if (n < 3) return 0.0L;
    long double s = 0.0L;
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        s += poly[i].x * poly[j].y - poly[i].y * poly[j].x;
    }
    return fabsl(s) * 0.5L;
}

// Clip the polygon by the half-plane defined by:
// line through P0 with direction dir = (cos theta, sin theta)
// We keep the points X with cross(dir, X - P0) >= 0.
static long double area_cut(const vector<P>& poly, const P& P0, long double theta) {
    long double c = cosl(theta), s = sinl(theta);
    P dir{c, s};
    auto inside = [&](const P& X) {
        long double val = cross(dir, X - P0);
        return val >= -1e-12L; // allow boundary
    };
    vector<P> out;
    if (poly.empty()) return 0.0L;
    int m = (int)poly.size();
    for (int i = 0; i < m; ++i) {
        const P& S = poly[i];
        const P& E = poly[(i + 1) % m];
        bool inS = inside(S);
        bool inE = inside(E);
        if (inS && inE) {
            out.push_back(E);
        } else if (inS && !inE) {
            // intersect SE with clipping line cross(dir, X-P0) = 0
            P d = E - S;
            long double denom = cross(dir, d);
            if (fabsl(denom) < 1e-18L) continue; // parallel, no intersection
            long double t = - cross(dir, S - P0) / denom;
            P I = S + d * t;
            out.push_back(I);
        } else if (!inS && inE) {
            P d = E - S;
            long double denom = cross(dir, d);
            if (fabsl(denom) < 1e-18L) {
                out.push_back(E);
                continue;
            }
            long double t = - cross(dir, S - P0) / denom;
            P I = S + d * t;
            out.push_back(I);
            out.push_back(E);
        } else {
            // both outside: contribute nothing
        }
    }
    return polygon_area(out);
}

